use std::io::{self, BufRead};
use std::env;

#[derive(Clone, Copy, Debug, PartialEq)]
enum Face {
    Added,
    Removed,
    RefineAdded,
    RefineRemoved,
}

#[derive(Clone, Debug, PartialEq)]
struct Style {
    fg: Option<Color>,
    bg: Option<Color>,
    bold: bool,
    italic: bool,
    underline: bool,
    intense: bool,
}

#[derive(Clone, Debug, PartialEq)]
enum Color {
    None,
    Ansi(u8),
    Rgb(u8, u8, u8),
}

impl Default for Style {
    fn default() -> Self {
        Style {
            fg: None,
            bg: None,
            bold: false,
            italic: false,
            underline: false,
            intense: false,
        }
    }
}

impl Style {
    fn to_ansi(&self, is_bg: bool) -> String {
        let mut codes = Vec::new();
        if let Some(color) = if is_bg { &self.bg } else { &self.fg } {
            match color {
                Color::None => {} // How to represent "none" color? 
                Color::Ansi(c) => {
                    let offset = if is_bg { 40 } else { 30 };
                    if *c < 8 {
                        codes.push(format!("{}", offset + c));
                    } else if *c < 16 {
                        codes.push(format!("{}", offset + 60 + (c - 8)));
                    } else {
                        codes.push(format!("{};5;{}", if is_bg { 48 } else { 38 }, c));
                    }
                }
                Color::Rgb(r, g, b) => {
                    codes.push(format!("{};2;{};{};{}", if is_bg { 48 } else { 38 }, r, g, b));
                }
            }
        }
        if !is_bg {
            if self.bold { codes.push("1".to_string()); }
            if self.italic { codes.push("3".to_string()); }
            if self.underline { codes.push("4".to_string()); }
            // Intense? ANSI 1 is usually bold, 2 is dim. Intense might be a different thing.
            // In many implementations, bold is also intense.
        }
        codes.join(";")
    }

    fn apply(&self) -> String {
        let mut codes = Vec::new();
        if let Some(ref fg) = self.fg {
            match fg {
                Color::None => {},
                Color::Ansi(c) => {
                    if *c < 8 { codes.push(format!("{}", 30 + c)); }
                    else if *c < 16 { codes.push(format!("{}", 90 + (c - 8))); }
                    else { codes.push(format!("38;5;{}", c)); }
                }
                Color::Rgb(r, g, b) => { codes.push(format!("38;2;{};{};{}", r, g, b)); }
            }
        }
        if let Some(ref bg) = self.bg {
            match bg {
                Color::None => {},
                Color::Ansi(c) => {
                    if *c < 8 { codes.push(format!("{}", 40 + c)); }
                    else if *c < 16 { codes.push(format!("{}", 100 + (c - 8))); }
                    else { codes.push(format!("48;5;{}", c)); }
                }
                Color::Rgb(r, g, b) => { codes.push(format!("48;2;{};{};{}", r, g, b)); }
            }
        }
        if self.bold { codes.push("1".to_string()); }
        if self.italic { codes.push("3".to_string()); }
        if self.underline { codes.push("4".to_string()); }
        if codes.is_empty() {
            "".to_string()
        } else {
            format!("\x1b[{}m", codes.join(";"))
        }
    }
}

fn parse_color(s: &str) -> Color {
    match s {
        "none" => Color::None,
        "black" => Color::Ansi(0),
        "red" => Color::Ansi(1),
        "green" => Color::Ansi(2),
        "yellow" => Color::Ansi(3),
        "blue" => Color::Ansi(4),
        "magenta" => Color::Ansi(5),
        "cyan" => Color::Ansi(6),
        "white" => Color::Ansi(7),
        _ => {
            if let Ok(c) = s.parse::<u8>() {
                Color::Ansi(c)
            } else if s.contains(',') {
                let parts: Vec<&str> = s.split(',').collect();
                if parts.len() == 3 {
                    if let (Ok(r), Ok(g), Ok(b)) = (parts[0].parse::<u8>(), parts[1].parse::<u8>(), parts[2].parse::<u8>()) {
                        return Color::Rgb(r, g, b);
                    }
                }
                Color::None
            } else {
                Color::None
            }
        }
    }
}

