        if codes.is_empty() {
            "".to_string()
        } else {
            format!("\x1b[{}m", codes.join(";"))
        }
    }
}

enum LineNumberStyle {
    Compact,
    Aligned,
}

struct Config {
    added: Style,
    removed: Style,
    refine_added: Style,
    refine_removed: Style,
    line_numbers: Option<LineNumberStyle>,
}

fn tokenize(s: &str) -> Vec<&str> {
    let mut tokens = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        let c = s[i..].chars().next().unwrap();
        if c.is_alphanumeric() || c == '_' {
            i += c.len_utf8();
            while i < bytes.len() {
                let next_c = s[i..].chars().next().unwrap();
                if next_c.is_alphanumeric() || next_c == '_' {
                    i += next_c.len_utf8();
                } else {
                    break;
                }
            }
            tokens.push(&s[start..i]);
        } else if c.is_whitespace() {
            i += c.len_utf8();
            while i < bytes.len() {
                let next_c = s[i..].chars().next().unwrap();
                if next_c.is_whitespace() {
                    i += next_c.len_utf8();
                } else {
                    break;
                }
            }
            tokens.push(&s[start..i]);
        } else {
            i += c.len_utf8();
            tokens.push(&s[start..i]);
        }
    }
    tokens
}

fn lcs(a: &[&str], b: &[&str]) -> Vec<(usize, usize)> {
    let n = a.len();
    let m = b.len();
    let mut dp = vec![vec![0; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]);
            }
        }
    }
    let mut res = Vec::new();
    let mut i = n;
    let mut j = m;
    while i > 0 && j > 0 {
        if a[i - 1] == b[j - 1] {
            res.push((i - 1, j - 1));
            i -= 1;
            j -= 1;
        } else if dp[i - 1][j] >= dp[i][j - 1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }
    res.reverse();
    res
}

fn parse_color(s: &str) -> Option<Color> {
    match s {
        "none" => Some(Color::None),
        "black" => Some(Color::Ansi(0)),
        "red" => Some(Color::Ansi(1)),
        "green" => Some(Color::Ansi(2)),
        "yellow" => Some(Color::Ansi(3)),
        "blue" => Some(Color::Ansi(4)),
        "magenta" => Some(Color::Ansi(5)),
        "cyan" => Some(Color::Ansi(6)),
        "white" => Some(Color::Ansi(7)),
        _ => {
            if let Ok(c) = s.parse::<u8>() {
                Some(Color::Ansi(c))
            } else if s.contains(',') {
                let parts: Vec<&str> = s.split(',').collect();
                if parts.len() == 3 {
                    if let (Ok(r), Ok(g), Ok(b)) = (parts[0].parse::<u8>(), parts[1].parse::<u8>(), parts[2].parse::<u8>()) {
                        return Some(Color::Rgb(r, g, b));
                    }
                }
                None
            } else {
                None
            }
        }
    }
}

fn parse_style(style: &mut Style, spec: &str) -> bool {
    let parts: Vec<&str> = spec.split(':').collect();
    let mut i = 0;
    while i < parts.len() {
        match parts[i] {
            "foreground" => {
                if i + 1 < parts.len() {
                    if let Some(c) = parse_color(parts[i+1]) {
                        style.fg = Some(c);
                        i += 2;
                        continue;
                    }
                }
                return false;
            }
            "background" => {
                if i + 1 < parts.len() {
                    if let Some(c) = parse_color(parts[i+1]) {
                        style.bg = Some(c);
                        i += 2;
                        continue;
                    }
                }
                return false;
            }
            "bold" => { style.bold = true; i += 1; }
            "nobold" => { style.bold = false; i += 1; }
            "italic" => { style.italic = true; i += 1; }
            "noitalic" => { style.italic = false; i += 1; }
            "underline" => { style.underline = true; i += 1; }
            "nounderline" => { style.underline = false; i += 1; }
            "intense" => { style.intense = true; i += 1; }
            "nointense" => { style.intense = false; i += 1; }
            "none" => { *style = Style::default(); i += 1; }
            _ => { return false; }
        }
    }
    true
}

fn main() {
    let mut config = Config {
        added: Style { fg: Some(Color::Ansi(2)), ..Style::default() },
        removed: Style { fg: Some(Color::Ansi(1)), ..Style::default() },
        refine_added: Style { 
            bold: true, 
            fg: Some(Color::Rgb(255, 255, 255)), 
            bg: Some(Color::Ansi(2)), 
            ..Style::default() 
        },
        refine_removed: Style { 
            bold: true, 
            fg: Some(Color::Rgb(255, 255, 255)), 
            bg: Some(Color::Ansi(1)), 
            ..Style::default() 
        },
        line_numbers: None,
    };

    let args: Vec<String> = env::args().collect();
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--colors" => {
                if i + 1 < args.len() {
                    let spec = &args[i+1];
                    let colon_idx = spec.find(':');
                    if let Some(idx) = colon_idx {
                        let face_name = &spec[..idx];
                        let style_spec = &spec[idx+1..];
                        let style = match face_name {
                            "added" => Some(&mut config.added),
                            "removed" => Some(&mut config.removed),
                            "refine-added" => Some(&mut config.refine_added),
                            "refine-removed" => Some(&mut config.refine_removed),
                            _ => None,
                        };
                        if let Some(s) = style {
                            if !parse_style(s, style_spec) {
                                eprintln!("unexpected attribute name: got '{}', expected ...", style_spec); // Simplified error
                                std::process::exit(1);
                            }
                        }
                    }
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--line-numbers" => {
                if i + 1 < args.len() && (args[i+1] == "compact" || args[i+1] == "aligned") {
                    config.line_numbers = Some(if args[i+1] == "aligned" { LineNumberStyle::Aligned } else { LineNumberStyle::Compact });
                    i += 2;
                } else {
                    config.line_numbers = Some(LineNumberStyle::Compact);
                    i += 1;
                }
            }
            "-h" | "--help" => {
                // Should print help, but let's just exit for now or implement later
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("diffr 0.1.5");
                std::process::exit(0);
            }
            _ => { i += 1; }
        }
    }

    let stdin = io::stdin();
    let mut lines = Vec::new();
    for line in stdin.lock().lines() {
        if let Ok(l) = line {
            lines.push(l);
        }
    }

    let mut current_line = 0;
    let mut old_ln = 0;
    let mut new_ln = 0;
    let mut max_ln = 0;

    while current_line < lines.len() {
        let line = &lines[current_line];
        if line.starts_with("@@") {
            // Parse hunk header
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 3 {
                // -start,len +start,len
                if let Some(comma_idx) = parts[1].find(',') {
                    old_ln = parts[1][1..comma_idx].parse().unwrap_or(0);
                } else {
                    old_ln = parts[1][1..].parse().unwrap_or(0);
                }
                if let Some(comma_idx) = parts[2].find(',') {
                    new_ln = parts[2][1..comma_idx].parse().unwrap_or(0);
                } else {
                    new_ln = parts[2][1..].parse().unwrap_or(0);
                }

                // Determine max line number for this hunk to get W
                let mut temp_old = old_ln;
                let mut temp_new = new_ln;
                let mut hunk_idx = current_line + 1;
                let mut hunk_max = 0;
                while hunk_idx < lines.len() {
                    let l = &lines[hunk_idx];
                    if l.starts_with(' ') { temp_old += 1; temp_new += 1; }
                    else if l.starts_with('-') { temp_old += 1; }
                    else if l.starts_with('+') { temp_new += 1; }
                    else { break; }
                    hunk_max = hunk_max.max(temp_old).max(temp_new);
                    hunk_idx += 1;
                }
                max_ln = hunk_max;
            }
            println!("\x1b[0m{}\x1b[0m", line);
            current_line += 1;
        } else if line.starts_with('---') || line.starts_with('+++') {
            println!("\x1b[0m{}\x1b[0m", line);
            current_line += 1;
        } else if line.starts_with('-') || line.starts_with('+') {
            // Collect block of removed/added lines
            let mut removed_lines = Vec::new();
            let mut added_lines = Vec::new();
            let mut block_idx = current_line;
            while block_idx < lines.len() {
                if lines[block_idx].starts_with('-') {
                    removed_lines.push(&lines[block_idx][1..]);
                    block_idx += 1;
                } else {
                    break;
                }
            }
            while block_idx < lines.len() {
                if lines[block_idx].starts_with('+') {
                    added_lines.push(&lines[block_idx][1..]);
                    block_idx += 1;
                } else {
                    break;
                }
            }

            let mut removed_full = String::new();
            for (j, l) in removed_lines.iter().enumerate() {
                removed_full.push_str(l);
                removed_full.push('\n');
            }
            let mut added_full = String::new();
            for (j, l) in added_lines.iter().enumerate() {
                added_full.push_str(l);
                added_full.push('\n');
