                while tok_idx < rem_tokens.len() {
                    let tok = rem_tokens[tok_idx];
                    let is_common = rem_is_common[tok_idx];
                    tok_idx += 1;
                    if tok == "\n" { break; }

                    if is_common {
                        print!("\x1b[0m{}\x1b[0m{}", config.removed.apply(), tok);
                    } else {
                        let mut style = config.refine_removed.clone();
                        let is_trailing = tok.chars().all(|c| c.is_whitespace()) && (tok_idx < rem_tokens.len() && rem_tokens[tok_idx] == "\n");
