                        } else {
                            print!("\x1b[0m\x1b[0m{}{}\x1b[0m\x1b[0m{}", style.apply(), tok, config.added.apply());
                        }
                    }
                }
                println!("\x1b[0m");
            }
            current_line = block_idx;
        } else if line.starts_with(' ') {
            let mut ln_str = String::new();
            if let Some(ref style) = config.line_numbers {
