                } else {
                    ln_str.push(' ');
                }
            }
            println!("\x1b[0m{}{}", ln_str, line);
            old_ln += 1;
            new_ln += 1;
            current_line += 1;
        } else {
            println!("\x1b[0m{}\x1b[0m", line);
            current_line += 1;
        }
    }
}
