                    }
                }
                println!("\x1b[0m");
            }
            let mut a_t_idx = 0;
            for _ in 0..add_lines.len() {
                print!("\x1b[0m");
                if let Some(ref style) = config.line_numbers {
                    print!("{}{}{:>width$}", config.added.apply(), " ".repeat(width + 1), new_ln);
