use std::io::{self, BufRead};
use std::env;

#[derive(Clone, Debug, PartialEq)]
enum Color {
    None,
    Ansi(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Debug, PartialEq)]
struct Style {
    fg: Option<Color>,
    bg: Option<Color>,
    bold: bool,
    italic: bool,
    underline: bool,
    intense: bool,
}

impl Default for Style {
    fn default() -> Self {
        Style {
            fg: None,
            bg: None,
            bold: false,
            italic: false,
            underline: false,
            intense: false,
        }
    }
}

impl Style {
    fn apply(&self) -> String {
        let mut res = String::new();
        if self.bold { res.push_str("\x1b[1m"); }
        if self.italic { res.push_str("\x1b[3m"); }
        if self.underline { res.push_str("\x1b[4m"); }
        if let Some(ref fg) = self.fg {
            match fg {
                Color::None => {},
                Color::Ansi(c) => {
                    if *c < 8 { res.push_str(&format!("\x1b[{}m", 30 + c)); }
                    else if *c < 16 { res.push_str(&format!("\x1b[{}m", 90 + (c - 8))); }
                    else { res.push_str(&format!("\x1b[38;5;{}m", c)); }
                }
                Color::Rgb(r, g, b) => { res.push_str(&format!("\x1b[38;2;{};{};{}m", r, g, b)); }
            }
        }
        if let Some(ref bg) = self.bg {
            match bg {
                Color::None => {},
                Color::Ansi(c) => {
                    if *c < 8 { res.push_str(&format!("\x1b[{}m", 40 + c)); }
                    else if *c < 16 { res.push_str(&format!("\x1b[{}m", 100 + (c - 8))); }
                    else { res.push_str(&format!("\x1b[48;5;{}m", c)); }
                }
                Color::Rgb(r, g, b) => { res.push_str(&format!("\x1b[48;2;{};{};{}m", r, g, b)); }
            }
        }
        res
    }
}

enum LineNumberStyle {
    Compact,
    Aligned,
}

struct Config {
    added: Style,
    removed: Style,
    refine_added: Style,
    refine_removed: Style,
    line_numbers: Option<LineNumberStyle>,
}

fn tokenize(s: &str) -> Vec<&str> {
    let mut tokens = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        let c = s[i..].chars().next().unwrap();
        if c.is_alphanumeric() || c == '_' {
            i += c.len_utf8();
            while i < bytes.len() {
                let next_c = s[i..].chars().next().unwrap();
                if next_c.is_alphanumeric() || next_c == '_' {
                    i += next_c.len_utf8();
                } else {
                    break;
                }
            }
            tokens.push(&s[start..i]);
        } else if c.is_whitespace() {
            i += c.len_utf8();
            while i < bytes.len() {
                let next_c = s[i..].chars().next().unwrap();
                if next_c.is_whitespace() {
                    i += next_c.len_utf8();
                } else {
                    break;
                }
            }
            tokens.push(&s[start..i]);
        } else {
            i += c.len_utf8();
            tokens.push(&s[start..i]);
        }
    }
    tokens
}

fn lcs(a: &[&str], b: &[&str]) -> Vec<(usize, usize)> {
    let n = a.len();
    let m = b.len();
    let mut dp = vec![vec![0; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]);
            }
        }
    }
    let mut res = Vec::new();
    let mut i = n;
    let mut j = m;
    while i > 0 && j > 0 {
        if a[i - 1] == b[j - 1] {
            res.push((i - 1, j - 1));
            i -= 1;
            j -= 1;
        } else if dp[i - 1][j] >= dp[i][j - 1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }
    res.reverse();
    res
}

fn parse_color(s: &str) -> Option<Color> {
    match s {
        "none" => Some(Color::None),
        "black" => Some(Color::Ansi(0)),
        "red" => Some(Color::Ansi(1)),
        "green" => Some(Color::Ansi(2)),
        "yellow" => Some(Color::Ansi(3)),
        "blue" => Some(Color::Ansi(4)),
        "magenta" => Some(Color::Ansi(5)),
        "cyan" => Some(Color::Ansi(6)),
        "white" => Some(Color::Ansi(7)),
