                        return Some(Color::Rgb(r, g, b));
                    }
                }
                None
            } else {
                None
            }
        }
    }
}

fn parse_style(style: &mut Style, spec: &str) -> bool {
    let parts: Vec<&str> = spec.split(':').collect();
    let mut i = 0;
    while i < parts.len() {
        match parts[i] {
            "foreground" => {
                if i + 1 < parts.len() {
                    if let Some(c) = parse_color(parts[i+1]) {
