            "noitalic" => { style.italic = false; i += 1; }
            "underline" => { style.underline = true; i += 1; }
            "nounderline" => { style.underline = false; i += 1; }
            "intense" => { style.intense = true; i += 1; }
            "nointense" => { style.intense = false; i += 1; }
            "none" => { *style = Style::default(); i += 1; }
            _ => { return false; }
        }
    }
    true
}

