                Color::Ansi(c) => {
                    if *c < 8 { res.push_str(&format!("\x1b[{}m", 30 + c)); }
                    else if *c < 16 { res.push_str(&format!("\x1b[{}m", 90 + (c - 8))); }
                    else { res.push_str(&format!("\x1b[38;5;{}m", c)); }
                }
                Color::Rgb(r, g, b) => { res.push_str(&format!("\x1b[38;2;{};{};{}m", r, g, b)); }
            }
        }
        if let Some(ref bg) = self.bg {
            match bg {
                Color::None => {},
                Color::Ansi(c) => {
                    if *c < 8 { res.push_str(&format!("\x1b[{}m", 40 + c)); }
                    else if *c < 16 { res.push_str(&format!("\x1b[{}m", 100 + (c - 8))); }
                    else { res.push_str(&format!("\x1b[48;5;{}m", c)); }
                }
                Color::Rgb(r, g, b) => { res.push_str(&format!("\x1b[48;2;{};{};{}m", r, g, b)); }
            }
        }
        res
    }
}

enum LineNumberStyle { Compact, Aligned }
struct Config {
    added: Style, removed: Style, refine_added: Style, refine_removed: Style,
    line_numbers: Option<LineNumberStyle>,
}

fn tokenize(s: &str) -> Vec<&str> {
    let mut tokens = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        let c = s[i..].chars().next().unwrap();
        if c.is_alphanumeric() || c == '_' {
            i += c.len_utf8();
            while i < bytes.len() {
                let next_c = s[i..].chars().next().unwrap();
                if next_c.is_alphanumeric() || next_c == '_' { i += next_c.len_utf8(); } else { break; }
            }
            tokens.push(&s[start..i]);
        } else if c.is_whitespace() {
            i += c.len_utf8();
            while i < bytes.len() {
                let next_c = s[i..].chars().next().unwrap();
                if next_c.is_whitespace() { i += next_c.len_utf8(); } else { break; }
            }
            tokens.push(&s[start..i]);
        } else {
            i += c.len_utf8();
            tokens.push(&s[start..i]);
        }
    }
    tokens
}

fn lcs(a: &[&str], b: &[&str]) -> Vec<(usize, usize)> {
    let n = a.len(); let m = b.len();
    let mut dp = vec![vec![0; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            if a[i - 1] == b[j - 1] { dp[i][j] = dp[i - 1][j - 1] + 1; }
            else { dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]); }
        }
    }
    let mut res = Vec::new();
    let (mut i, mut j) = (n, m);
    while i > 0 && j > 0 {
        if a[i - 1] == b[j - 1] { res.push((i - 1, j - 1)); i -= 1; j -= 1; }
        else if dp[i - 1][j] >= dp[i][j - 1] { i -= 1; }
        else { j -= 1; }
    }
    res.reverse(); res
}

fn parse_color(s: &str) -> Option<Color> {
    match s {
        "none" => Some(Color::None), "black" => Some(Color::Ansi(0)), "red" => Some(Color::Ansi(1)),
        "green" => Some(Color::Ansi(2)), "yellow" => Some(Color::Ansi(3)), "blue" => Some(Color::Ansi(4)),
        "magenta" => Some(Color::Ansi(5)), "cyan" => Some(Color::Ansi(6)), "white" => Some(Color::Ansi(7)),
        _ => {
            if let Ok(c) = s.parse::<u8>() { Some(Color::Ansi(c)) }
            else if s.contains(',') {
                let parts: Vec<&str> = s.split(',').collect();
                if parts.len() == 3 {
                    if let (Ok(r), Ok(g), Ok(b)) = (parts[0].parse::<u8>(), parts[1].parse::<u8>(), parts[2].parse::<u8>()) {
                        return Some(Color::Rgb(r, g, b));
                    }
                }
                None
            } else { None }
        }
    }
}

fn parse_style(style: &mut Style, spec: &str) -> bool {
    let parts: Vec<&str> = spec.split(':').collect();
    let mut i = 0;
    while i < parts.len() {
        match parts[i] {
            "foreground" => {
                if i + 1 < parts.len() {
                    if let Some(c) = parse_color(parts[i+1]) { style.fg = Some(c); i += 2; continue; }
                }
                return false;
            }
            "background" => {
                if i + 1 < parts.len() {
                    if let Some(c) = parse_color(parts[i+1]) { style.bg = Some(c); i += 2; continue; }
                }
                return false;
            }
            "bold" => { style.bold = true; i += 1; } "nobold" => { style.bold = false; i += 1; }
            "italic" => { style.italic = true; i += 1; } "noitalic" => { style.italic = false; i += 1; }
            "underline" => { style.underline = true; i += 1; } "nounderline" => { style.underline = false; i += 1; }
            "intense" => { style.intense = true; i += 1; } "nointense" => { style.intense = false; i += 1; }
            "none" => { *style = Style::default(); i += 1; } _ => { return false; }
        }
    }
    true
}

fn process_block(rem: &[String], add: &[String], config: &Config, old_ln: &mut usize, new_ln: &mut usize, max_ln: usize) {
    let mut rem_f = String::new();
    for l in rem { rem_f.push_str(&l[1..]); rem_f.push('\n'); }
    let mut add_f = String::new();
    for l in add { add_f.push_str(&l[1..]); add_f.push('\n'); }

    let rem_t = tokenize(&rem_f);
    let add_t = tokenize(&add_f);
    let comm = lcs(&rem_t, &add_t);
    let mut r_is_c = vec![false; rem_t.len()];
    let mut a_is_c = vec![false; add_t.len()];
    for (r, a) in comm { r_is_c[r] = true; a_is_c[a] = true; }

    let width = format!("{}", max_ln).len();
    let mut r_t_idx = 0;
    for _ in 0..rem.len() {
        print!("\x1b[0m");
        if let Some(ref style) = config.line_numbers {
            print!("{}{:>width$}{}", config.removed.apply(), *old_ln, " ".repeat(width + 1));
            *old_ln += 1;
            print!("\x1b[0m{}", if let LineNumberStyle::Aligned = style { "\t" } else { " " });
        }
        print!("{}\x1b[0m-", config.removed.apply());
        while r_t_idx < rem_t.len() {
            let tok = rem_t[r_t_idx]; let is_c = r_is_c[r_t_idx]; r_t_idx += 1;
            if tok == "\n" { break; }
            if is_c { print!("\x1b[0m{}\x1b[0m{}", config.removed.apply(), tok); }
            else {
                let is_t = tok.chars().all(|c| c.is_whitespace()) && (r_t_idx < rem_t.len() && rem_t[r_t_idx] == "\n");
                if is_t { print!("\x1b[0m\x1b[41m{}\x1b[0m\x1b[0m{}", tok, config.removed.apply()); }
                else { print!("\x1b[0m\x1b[0m{}{}\x1b[0m\x1b[0m{}", config.refine_removed.apply(), tok, config.removed.apply()); }
            }
        }
        println!("\x1b[0m");
    }
    let mut a_t_idx = 0;
    for _ in 0..add.len() {
        print!("\x1b[0m");
        if let Some(ref style) = config.line_numbers {
            print!("{}{}{:>width$}", config.added.apply(), " ".repeat(width + 1), *new_ln);
            *new_ln += 1;
            print!("\x1b[0m{}", if let LineNumberStyle::Aligned = style { "\t" } else { " " });
        }
        print!("{}\x1b[0m+", config.added.apply());
        while a_t_idx < add_t.len() {
            let tok = add_t[a_t_idx]; let is_c = a_is_c[a_t_idx]; a_t_idx += 1;
            if tok == "\n" { break; }
            if is_c { print!("\x1b[0m{}\x1b[0m{}", config.added.apply(), tok); }
            else {
                let is_t = tok.chars().all(|c| c.is_whitespace()) && (a_t_idx < add_t.len() && add_t[a_t_idx] == "\n");
                if is_t { print!("\x1b[0m\x1b[41m{}\x1b[0m\x1b[0m{}", tok, config.added.apply()); }
                else { print!("\x1b[0m\x1b[0m{}{}\x1b[0m\x1b[0m{}", config.refine_added.apply(), tok, config.added.apply()); }
            }
        }
        println!("\x1b[0m");
    }
}

fn main() {
    let mut config = Config {
        added: Style { fg: Some(Color::Ansi(2)), ..Style::default() },
        removed: Style { fg: Some(Color::Ansi(1)), ..Style::default() },
        refine_added: Style { bold: true, fg: Some(Color::Rgb(255, 255, 255)), bg: Some(Color::Ansi(2)), ..Style::default() },
        refine_removed: Style { bold: true, fg: Some(Color::Rgb(255, 255, 255)), bg: Some(Color::Ansi(1)), ..Style::default() },
        line_numbers: None,
    };
    let args: Vec<String> = env::args().collect();
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--colors" => {
                if i + 1 < args.len() {
                    let spec = &args[i+1];
                    if let Some(idx) = spec.find(':') {
                        let face = &spec[..idx]; let s_spec = &spec[idx+1..];
                        let style = match face { "added" => Some(&mut config.added), "removed" => Some(&mut config.removed), "refine-added" => Some(&mut config.refine_added), "refine-removed" => Some(&mut config.refine_removed), _ => None };
                        if let Some(s) = style { if !parse_style(s, s_spec) { eprintln!("unexpected attribute name: got '{}', expected ...", s_spec); std::process::exit(1); } }
                    }
                    i += 2;
                } else { i += 1; }
            }
            "--line-numbers" => {
                if i + 1 < args.len() && (args[i+1] == "compact" || args[i+1] == "aligned") { config.line_numbers = Some(if args[i+1] == "aligned" { LineNumberStyle::Aligned } else { LineNumberStyle::Compact }); i += 2; }
                else { config.line_numbers = Some(LineNumberStyle::Compact); i += 1; }
            }
            "-h" | "--help" => { println!("diffr 0.1.5\nNathan Moreau <nathan.moreau@m4x.org>\n\ndiffr adds word-level diff on top of unified diffs.\nword-level diff information is displayed using text attributes.\n\nUSAGE:\n    diffr reads from standard input and writes to standard output.\n\n    Typical usage is for interactive use of diff:\n    diff -u <file1> <file2> | diffr\n    git show | diffr\n\nOPTIONS:\n        --colors <COLOR_SPEC>...\n            Configure color settings for console ouput.\n\n            There are four faces to customize:\n            +----------------+--------------+----------------+\n            |  line prefix   |      +       |       -        |\n            +----------------+--------------+----------------+\n            | common segment |    added     |    removed     |\n            | unique segment | refine-added | refine-removed |\n            +----------------+--------------+----------------+\n\n            The customization allows\n            - to change the foreground or background color;\n            - to set or unset the attributes 'bold', 'intense', 'underline';\n            - to clear all attributes.\n\n            Customization is done passing a color_spec argument.\n            This flag may be provided multiple times.\n\n            The syntax is the following:\n\n            color_spec = face-name + ':' + attributes\n            attributes = attribute\n                       | attribute + ':' + attributes\n            attribute  = ('foreground' | 'background') + ':' + color\n                       | (<empty> | 'no') + font-flag\n                       | 'none'\n            font-flag  = 'italic'\n                       | 'bold'\n                       | 'intense'\n                       | 'underline'\n            color      = 'none'\n                       | [0-255]\n                       | [0-255] + ',' + [0-255] + ',' + [0-255]\n                       | ('black', 'blue', 'green', 'red',\n                          'cyan', 'magenta', 'yellow', 'white')\n\n            For example, the color_spec\n\n                'refine-added:background:blue:bold'\n\n            sets the color of unique added segments with\n            a blue background, written with a bold font.\n\n        --line-numbers <compact|aligned>\n            Display line numbers. Style is optional.\n            When style = 'compact', take as little width as possible.\n            When style = 'aligned', align to tab stops (useful if tab is used for indentation). [default: compact]\n\n    -h, --help\n            Prints help information\n\n    -V, --version\n            Prints version information"); std::process::exit(0); }
            "-V" | "--version" => { println!("diffr 0.1.5"); std::process::exit(0); }
            _ => { i += 1; }
        }
    }
    let stdin = io::stdin();
    let mut old_ln = 0; let mut new_ln = 0; let mut max_ln = 0;
    let mut rem_lines = Vec::new(); let mut add_lines = Vec::new();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        if line.starts_with('-') {
            if !add_lines.is_empty() { process_block(&rem_lines, &add_lines, &config, &mut old_ln, &mut new_ln, max_ln); rem_lines.clear(); add_lines.clear(); }
            rem_lines.push(line);
        } else if line.starts_with('+') { add_lines.push(line); }
        else {
            if !rem_lines.is_empty() || !add_lines.is_empty() { process_block(&rem_lines, &add_lines, &config, &mut old_ln, &mut new_ln, max_ln); rem_lines.clear(); add_lines.clear(); }
            if line.starts_with("@@") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 3 {
                    let o_part = if let Some(c) = parts[1].find(',') { &parts[1][1..c] } else { &parts[1][1..] };
                    let n_part = if let Some(c) = parts[2].find(',') { &parts[2][1..c] } else { &parts[2][1..] };
                    old_ln = o_part.parse().unwrap_or(0); new_ln = n_part.parse().unwrap_or(0);
                    let o_len = if let Some(c) = parts[1].find(',') { parts[1][c+1..].parse().unwrap_or(1) } else { 1 };
                    let n_len = if let Some(c) = parts[2].find(',') { parts[2][c+1..].parse().unwrap_or(1) } else { 1 };
                    max_ln = (old_ln + o_len - 1).max(new_ln + n_len - 1);
                }
                println!("\x1b[0m{}\x1b[0m", line);
            } else if line.starts_with("---") || line.starts_with("+++") { println!("\x1b[0m{}\x1b[0m", line); }
            else if line.starts_with(' ') {
                print!("\x1b[0m");
                if let Some(ref style) = config.line_numbers {
                    let width = format!("{}", max_ln).len();
                    print!("{}{:>width$}", " ".repeat(width + 1), new_ln);
                    print!("{}", if let LineNumberStyle::Aligned = style { "\t" } else { " " });
                }
                println!("{}", line);
                old_ln += 1; new_ln += 1;
            } else { println!("\x1b[0m{}\x1b[0m", line); }
        }
    }
    if !rem_lines.is_empty() || !add_lines.is_empty() { process_block(&rem_lines, &add_lines, &config, &mut old_ln, &mut new_ln, max_ln); }
}
