                let next_c = s[i..].chars().next().unwrap();
                if next_c.is_whitespace() { i += next_c.len_utf8(); } else { break; }
            }
            tokens.push(&s[start..i]);
        } else {
            i += c.len_utf8();
            tokens.push(&s[start..i]);
        }
    }
    tokens
