fn lcs(a: &[&str], b: &[&str]) -> Vec<(usize, usize)> {
    let n = a.len(); let m = b.len();
    let mut dp = vec![vec![0; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            if a[i - 1] == b[j - 1] { dp[i][j] = dp[i - 1][j - 1] + 1; }
            else { dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]); }
        }
    }
    let mut res = Vec::new();
    let (mut i, mut j) = (n, m);
    while i > 0 && j > 0 {
        if a[i - 1] == b[j - 1] { res.push((i - 1, j - 1)); i -= 1; j -= 1; }
        else if dp[i - 1][j] >= dp[i][j - 1] { i -= 1; }
        else { j -= 1; }
    }
    res.reverse(); res
}

